<template>
    <div class="backpack">
        <div v-if="chooseCan" class="btnBox">
            <a-button type="text" @click="sort">
                排序
                {{
                    sortType === "0" ? "-" :
                        sortType === "1" ? "↓" : "↑"
                }}
            </a-button>
            <a-button type="text" @click="chooseAll(true)">
                全选
            </a-button>
            <a-button type="text" @click="chooseAll(false)">
                全不选
            </a-button>
            <a-button type="text" @click="dissolveAll">
                批量分解
            </a-button>
        </div>
        <a-menu
            :items="menuList"
            :selectedKeys="selectedKeys"
            mode="horizontal"
            @click="menuClick"
        />
        <div class="content">
            <div
                v-for="(item, index) in backpackList"
                :class="{ choose: item.isChoose }"
                class="items"
                @click="chooseItem(item, index)"
            >
                <p class="name">
                    <Iconfont v-if="item.type === '2'" type="wx-attacker1">
                    </Iconfont>
                    <Iconfont
                        v-if="item.type === '3'"
                        type="wx-clothes"
                    ></Iconfont>
                    <Iconfont
                        v-if="item.type === '4'"
                        type="wx-jiezhi1"
                    ></Iconfont>
                    {{ item.name }}
                </p>
                <p>
                    <span v-for="item in item.attr" class="attr">
                        <span class="br"> - </span>
                        <span>{{ item.nameText }}: {{ item.desc }}</span>
                    </span>
                </p>
                <p class="status">
                    <a-button
                        v-if="item.status === '1'"
                        type="primary"
                        @click="useItem(item)"
                    >
                        {{ $t("use") }}
                    </a-button>
                    <a-button
                        v-if="item.status === '2'"
                        type="primary"
                        @click="equipItem(item)"
                    >
                        {{ $t("equip") }}
                    </a-button>
                    <a-button
                        v-if="item.status === '2'"
                        style="margin-left: 10px"
                        type="primary"
                        @click="dissolveItem(item)"
                    >
                        {{ $t("dissolve") }}
                    </a-button>
                    <a-button v-if="item.status === '21'" disabled type="text">
                        E
                    </a-button>
                    <a-button
                        v-if="item.status === '11'"
                        disabled
                        type="primary"
                    >
                        {{ $t("used") }}
                    </a-button>
                    <a-button
                        v-if="item.status === '21'"
                        style="margin-left: 5px"
                        type="primary"
                        @click="unEquipItem(item)"
                    >
                        {{ $t("equiped") }}
                    </a-button>
                </p>
            </div>
            <a-result v-if="backpackList.length === 0" :title="$t('noItem')">
                <template #icon></template>
            </a-result>
        </div>
    </div>
</template>

<script>
import {
    reactive,
    toRefs,
    onMounted,
    ref,
    h,
    watch,
    computed,
    createVNode
} from "vue";
import backpackApi from "@/assets/api/backpackApi";
import backpackMenu from "@/assets/config/backpackMenu.js";
import { useI18n } from "vue-i18n";
import { transItemText, transItemType } from "@/assets/common/transItemText";
import { SmileTwoTone } from "@ant-design/icons-vue";
import Iconfont from "@/components/Iconfont.vue";
import { message, Modal } from "ant-design-vue";
import fightApi from "@/assets/api/fightApi";

export default {
    name: "Backpack", // 背包
    components: { Iconfont },
    setup() {
        const { t, locale } = useI18n();
        const state = reactive({
            menuList: backpackMenu,
            selectedKeys: ["all"], // 当前选中项key
            selectItemType: "", // 当前选中项 item type
            sortType: "0", // 排序类型 0-默认 1-降序 2-升序

            oriList: [], // 原始列表
            backpackList: [] // 背包列表
        });

        onMounted(async () => {
            // 根据语言修改 menu label
            changeLocaleLabel();
            // 获取背包信息
            await getBackpackInfo();
        });

        // 获取背包信息
        const getBackpackInfo = async () => {
            let res = await backpackApi.getList({
                uid: sessionStorage.getItem("uid"),
                type: state.selectItemType
            });
            state.backpackList = res.data.map((i) => {
                let attr = transItemText(i.attr);

                // 计算战力
                let points = attr.map(i => i.desc);
                let point = 0;
                points.forEach(i => {
                    point += Number(i);
                });

                return {
                    ...i,
                    attr: attr,
                    typeText: transItemType(i.type),
                    isChoose: false,
                    point: point
                };
            });
            state.oriList = JSON.parse(JSON.stringify(state.backpackList));
        };

        // btn 权限
        const chooseCan = computed(() => {
            return ["", "2", "3", "4"].includes(state.selectItemType);
        });

        // 排序 循环 0-默认 1-降序 2-升序
        const sort = () => {
            switch (state.sortType) {
                case "0":
                    state.backpackList.sort((a, b) => b.point - a.point);
                    state.sortType = "1";
                    break;
                case "1":
                    state.backpackList.sort((a, b) => a.point - b.point);
                    state.sortType = "2";
                    break;
                case "2":
                    state.backpackList = JSON.parse(JSON.stringify(state.oriList));
                    state.sortType = "0";
                    break;
            }
        };

        // 选中道具
        const chooseItem = async (item, index) => {
            state.backpackList[index].isChoose = !state.backpackList[index].isChoose;
        };

        // 全选/反选
        const chooseAll = async (bool) => {
            state.backpackList.forEach(i => i.isChoose = false);
            if (bool) {
                state.backpackList.filter(i => i.status !== "21" && ["2", "3", "4"].includes(i.type)).forEach(i => i.isChoose = true);
            }
            message.success(bool ? "已选择所有未穿戴装备！" : "已取消所有选择！");
        };

        // 选中道具的数组
        const itemChooseList = computed(() => {
            return state.backpackList.filter((i) => i.isChoose);
        });

        // 提交全部分解
        const dissolveAll = async () => {
            if (itemChooseList.value.length === 0) {
                message.error("请选中道具！");
                return;
            }

            if (itemChooseList.value.filter(i => i.status === "21").length !== 0) {
                message.error("请选择未穿戴装备！");
                return;
            }

            //  二次确认
            Modal.confirm({
                title: `是否分解全部 ${itemChooseList.value.length}件 道具?`,
                content: createVNode("div", { style: "color:red;" }),
                okText: "确定",
                cancelText: "取消",
                async onOk() {
                    await backpackApi.postDissolveAll({
                        ids: itemChooseList.value.map(i => i.id)
                    });

                    // 获取背包信息
                    await getBackpackInfo();
                }
            });
        };

        // 提交分解装备
        const dissolveItem = async (item) => {
            Modal.confirm({
                title: `是否分解 ${item.name}?`,
                content: createVNode("div", { style: "color:red;" }),
                okText: "确定",
                cancelText: "取消",
                async onOk() {
                    await backpackApi.postDissolve({
                        id: item.id,
                        uid: sessionStorage.getItem("uid")
                    });

                    // 获取背包信息
                    await getBackpackInfo();
                }
            });
        };

        // 提交装备道具
        const equipItem = async (item) => {
            let res = await backpackApi.postEquip({
                id: item.id,
                uid: sessionStorage.getItem("uid"),
                type: item.type
            });

            // 获取背包信息
            await getBackpackInfo();
        };

        // 提交卸下道具
        const unEquipItem = async (item) => {
            let res = await backpackApi.postUnEquip({
                id: item.id
            });

            // 获取背包信息
            await getBackpackInfo();
        };

        // 提交使用道具
        const useItem = async (item) => {
            let res = await backpackApi.postUse({
                id: item.id
            });

            // 获取背包信息
            await getBackpackInfo();
        };

        // 菜单点击
        const menuClick = async (item, key, keyPath) => {
            // console.log(item, key, keyPath);
            // 当前选中项
            state.selectedKeys = [item.key];
            state.selectItemType = item.item.itemType;
            state.sortType = "0";
            // 获取背包信息
            await getBackpackInfo();
        };

        // 监听语言改变
        watch(
            locale,
            () => {
                // 根据语言修改 menu label
                changeLocaleLabel();
            },
            { deep: true }
        );

        // 根据语言修改 menu label
        const changeLocaleLabel = () => {
            for (let key in state.menuList) {
                let text = t(state.menuList[key].key);
                state.menuList[key].label = text;
                state.menuList[key].title = text;
            }
        };

        return {
            ...toRefs(state),
            chooseCan,
            sort,
            chooseItem,
            chooseAll,
            equipItem,
            unEquipItem,
            useItem,
            menuClick,
            SmileTwoTone,
            dissolveItem,
            dissolveAll
        };
    }
};
</script>

<style lang="scss" scoped>
.backpack {
    margin: 10px;
    position: relative;

    .btnBox {
        position: absolute;
        right: 0;
        top: 0;
        height: 46px;
        display: flex;
        align-items: center;
    }

    .content {
        margin-top: 10px;
        overflow: hidden;

        .items {
            float: left;
            border-radius: 8px;
            padding: 10px 10px 0;
            border: 1px solid #d2d2d2;
            margin-right: 10px;
            margin-bottom: 10px;
            cursor: pointer;

            .br {
                padding: 0 5px;
            }

            .status {
                display: flex;
                align-items: center;
                justify-content: center;
            }
        }

        .choose {
            border: 1px solid deepskyblue;
        }
    }
}
</style>
